//! Original fixed-layout Acorn DFS SSD encoder from public catalogue facts.
use eightbit_source_core::{Result, error};
pub const IMAGE_SIZE: usize = 80 * 10 * 256;
/// Only original generated BASIC discs are recoverable; no arbitrary DFS import.
pub fn recover_basic(image: &[u8]) -> Result<String> {
    let invalid = || {
        error(
            "DBBC103",
            "Choose a BASIC SSD generated by Eightbit Studio for BBC Model B",
        )
    };
    if image.len() != IMAGE_SIZE {
        return Err(invalid());
    }
    let length = usize::from(u16::from_le_bytes([image[268], image[269]]))
        | (usize::from((image[270] >> 4) & 3) << 16);
    if length == 0 || length > crate::PROGRAM_LIMIT {
        return Err(invalid());
    }
    let program = &image[768..768 + length];
    if package(program, false)? != image {
        return Err(invalid());
    }
    crate::basic::decompile(program)
}

pub fn package(program: &[u8], assembly: bool) -> Result<Vec<u8>> {
    if program.is_empty() || program.len() > crate::PROGRAM_LIMIT {
        return Err(error(
            "DBBC102",
            "Programme exceeds the supported BBC memory range",
        ));
    }
    let boot: &[u8] = if assembly {
        b"MODE 7\r*RUN PROGRAM\r"
    } else {
        b"MODE 7\rCHAIN \"PROGRAM\"\r"
    };
    let mut image = vec![0; IMAGE_SIZE];
    image[..8].copy_from_slice(b"EIGHTBIT");
    image[256..260].copy_from_slice(b"BBC ");
    image[261] = 16; // Two catalogue entries.
    image[262] = 0x33; // *OPT 4,3 (EXEC), plus the high bits of 800 sectors.
    image[263] = 0x20;
    // DFS catalogue entries descend by start sector; no image input is accepted.
    entry(
        &mut image,
        8,
        *b"PROGRAM",
        3,
        program,
        u32::from(crate::ORIGIN),
    )?;
    entry(&mut image, 16, *b"!BOOT  ", 2, boot, 0)?;
    Ok(image)
}
fn entry(
    image: &mut [u8],
    index: usize,
    name: [u8; 7],
    sector: u16,
    bytes: &[u8],
    address: u32,
) -> Result<()> {
    let length = u32::try_from(bytes.len()).map_err(|_| error("DBBC102", "DFS length overflow"))?;
    let start = usize::from(sector) * 256;
    let destination = image
        .get_mut(start..start + bytes.len())
        .ok_or_else(|| error("DBBC102", "DFS disc is full"))?;
    destination.copy_from_slice(bytes);
    image[index..index + 7].copy_from_slice(&name);
    image[index + 7] = b'$';
    let meta = 256 + index;
    image[meta..meta + 2].copy_from_slice(&address.to_le_bytes()[..2]);
    image[meta + 2..meta + 4].copy_from_slice(&address.to_le_bytes()[..2]);
    image[meta + 4..meta + 6].copy_from_slice(&length.to_le_bytes()[..2]);
    image[meta + 6] = u8::try_from(
        (u32::from(sector) >> 8)
            | ((address >> 16) << 2)
            | ((length >> 16) << 4)
            | ((address >> 16) << 6),
    )
    .map_err(|_| error("DBBC102", "DFS catalogue address overflow"))?;
    image[meta + 7] = sector.to_le_bytes()[0];
    Ok(())
}

#[cfg(test)]
mod portable_tests {
    use super::*;
    #[test]
    fn disc_recovery_rejects_assembly_extra_content_and_corrupt_catalogues() {
        let source = crate::PROFILES[0].basic_template;
        let bytes = crate::basic::compile(source).unwrap();
        let image = package(&bytes, false).unwrap();
        assert_eq!(recover_basic(&image).unwrap(), source);
        assert!(recover_basic(&package(&bytes, true).unwrap()).is_err());
        for offset in [0, 8, 15, 261, 262, 263, 264, 268, 270, 271, IMAGE_SIZE - 1] {
            let mut bad = image.clone();
            bad[offset] ^= 1;
            assert!(recover_basic(&bad).is_err());
        }
        for size in [0, 512, IMAGE_SIZE - 1] {
            assert!(recover_basic(&image[..size]).is_err());
        }
    }
}
